echo '== чим запущено caddy =='
ps -o args= -p $(pgrep -x caddy | head -1) | head -c 200; echo
echo '== живий конфіг (маршрути) =='
curl -s localhost:2019/config/ -o /root/caddy_running.json && python3 - <<'PY'
import json
c = json.load(open('/root/caddy_running.json'))
srv = c.get('apps', {}).get('http', {}).get('servers', {})
for name, s in srv.items():
    print('сервер', name, 'порти', s.get('listen'))
    for i, rt in enumerate(s.get('routes', [])):
        hosts = [h for m in rt.get('match', []) for h in m.get('host', [])]
        paths = [p for m in rt.get('match', []) for p in m.get('path', [])]
        hs = rt.get('handle', [])
        kinds = []
        for h in hs:
            k = h.get('handler')
            if k == 'reverse_proxy':
                k += '→' + ','.join(u.get('dial','') for u in h.get('upstreams', []))
            if k == 'subroute':
                for r2 in h.get('routes', []):
                    p2 = [p for m in r2.get('match', []) for p in m.get('path', [])]
                    h2 = []
                    for hh in r2.get('handle', []):
                        kk = hh.get('handler')
                        if kk == 'reverse_proxy': kk += '→' + ','.join(u.get('dial','') for u in hh.get('upstreams', []))
                        if kk == 'vars': kk += ' root=' + str(hh.get('root'))
                        if kk == 'file_server': kk += ' root=' + str(hh.get('root'))
                        h2.append(kk)
                    print('    ', p2 or '(усе)', '→', ' | '.join(h2))
            kinds.append(k)
        print('  маршрут', i, 'host=', hosts, 'path=', paths, '→', kinds)
PY

